<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StockReserve | Inventory API</title><style>
:root{font-family:system-ui,sans-serif;color:#193528;background:#edf3ef}body{margin:0}header{background:#173e2d;color:white;padding:28px max(5vw,20px)}header small{color:#b6d9c2}main{max-width:1100px;margin:30px auto;padding:0 20px}h1{margin:4px 0}h2{font-size:19px}section{background:white;border:1px solid #d9e4dc;border-radius:14px;padding:24px;margin:18px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}input,button{padding:11px;border-radius:7px;border:1px solid #c1d2c6;margin:4px 4px 4px 0;font:inherit}button{background:#236d46;color:white;cursor:pointer}button.secondary{background:#66796c}input{max-width:90%}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px 8px;border-bottom:1px solid #e6ede8}#message{white-space:pre-wrap;padding:15px;border-radius:8px;background:#dce9e0;min-height:24px}.badge{font-size:12px;background:#e7f2eb;padding:5px 9px;border-radius:20px}code{font-size:12px}button:disabled{opacity:.5}#workspace{display:none}.muted{color:#62766a;font-size:14px}@media(max-width:720px){.grid{grid-template-columns:1fr}table{font-size:12px}td,th{padding:8px 3px}input{width:90%}} </style></head><body>
<header><small>BACKEND ENGINEERING PORTFOLIO</small><h1>StockReserve</h1><p>Reserve inventory. Prevent overselling. Keep a clear audit trail.</p></header><main>
<div id="message" role="status" aria-live="polite">Log in or create a customer account to explore the API.</div>
<section id="auth"><div class="grid"><div><h2>Log in</h2><p class="muted">Seeded accounts: customer@example.test / admin@example.test. Use your DEMO_PASSWORD.</p><form id="login"><label>Email<br><input type="email" name="email" required autocomplete="username"></label><br><label>Password<br><input type="password" name="password" required autocomplete="current-password"></label><br><button>Log in</button></form></div><div><h2>Create a customer account</h2><form id="register"><label>Name<br><input name="name" required maxlength="100"></label><br><label>Email<br><input type="email" name="email" required></label><br><label>Password (12+ characters)<br><input type="password" name="password" required minlength="12" autocomplete="new-password"></label><br><button>Create account</button></form></div></div></section>
<div id="workspace"><section><button id="refresh">Refresh inventory</button><button id="logout" class="secondary">Log out</button><h2>Available products</h2><p class="muted">Reservations expire after 15 minutes. Run the scheduler to release stock automatically.</p><table><thead><tr><th>Product</th><th>Stock</th><th>Quantity</th><th>Action</th></tr></thead><tbody id="products"></tbody></table></section>
<section><h2>Your reservations</h2><table><thead><tr><th>Product / reference</th><th>Qty</th><th>Status</th><th>Action</th></tr></thead><tbody id="reservations"></tbody></table></section>
<section><h2>Admin: create a product</h2><p class="muted">Only the admin account can use this action.</p><form id="product"><input name="sku" placeholder="SKU" aria-label="SKU" required><input name="name" placeholder="Product name" aria-label="Product name" required><input name="available" type="number" min="0" max="1000000" placeholder="Initial stock" aria-label="Initial stock" required><button>Create product</button></form></section></div>
<section><h2>What this project demonstrates</h2><p>Atomic stock updates · Database transactions · Idempotency keys · Token authentication · Ownership checks · Reservation expiry · Audit events</p><p class="muted">This is a portfolio demo, not a payment or warehouse production system. API docs: docs/API.md in the repository.</p></section></main>
<script>
let token=null;const el=id=>document.getElementById(id);const msg=s=>el('message').textContent=s;
async function api(path,method='GET',data=null,key=null){const h={'Accept':'application/json'};if(token)h.Authorization='Bearer '+token;if(data)h['Content-Type']='application/json';if(key)h['Idempotency-Key']=key;const r=await fetch('/api/v1'+path,{method,headers:h,body:data?JSON.stringify(data):null});const b=r.status===204?{}:await r.json();if(!r.ok)throw Error(b.message||'Request failed');return b;}
function node(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
async function load(){const [p,r]=await Promise.all([api('/products'),api('/reservations')]);el('products').replaceChildren();for(const item of p.data){const row=node('tr');row.append(node('td',item.name+' ('+item.sku+')'),node('td',item.available));const cell=node('td'),qty=node('input');qty.type='number';qty.min='1';qty.max='1000';qty.value='1';qty.style.width='60px';qty.setAttribute('aria-label','Quantity for '+item.name);cell.append(qty);row.append(cell);const a=node('td'),button=node('button','Reserve');let pendingKey=null;button.onclick=async()=>{button.disabled=true;try{pendingKey=pendingKey||crypto.randomUUID();const b=await api('/reservations','POST',{product_id:item.id,quantity:Number(qty.value)},pendingKey);msg('Reserved '+b.data.quantity+' units. Reference: '+b.data.id);pendingKey=null;await load();}catch(e){msg(e.message);}finally{button.disabled=false;}};a.append(button);row.append(a);el('products').append(row);}el('reservations').replaceChildren();for(const item of r.data){const row=node('tr');row.append(node('td','Product '+item.product_id+' / '+item.id.slice(0,8)),node('td',item.quantity),node('td',item.status));const a=node('td');if(item.status==='pending')for(const action of ['confirm','cancel']){const b=node('button',action);b.onclick=async()=>{b.disabled=true;try{const result=await api('/reservations/'+item.id+'/'+action,'POST');msg('Reservation '+result.status);await load();}catch(e){msg(e.message);}finally{b.disabled=false;}};a.append(b);}row.append(a);el('reservations').append(row);}}
for(const action of ['login','register'])el(action).onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));const b=await api('/'+action,'POST',d);token=b.token;el('auth').style.display='none';el('workspace').style.display='block';e.target.reset();msg('Signed in. Token stays in memory and is cleared when this page reloads.');await load();}catch(e){msg(e.message);}};
el('product').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.available=Number(d.available);await api('/products','POST',d);e.target.reset();await load();msg('Product created.');}catch(e){msg(e.message);}};
el('refresh').onclick=()=>load().catch(e=>msg(e.message));el('logout').onclick=async()=>{try{await api('/logout','POST');token=null;el('workspace').style.display='none';el('auth').style.display='block';msg('Logged out.');}catch(e){msg(e.message);}};
</script></body></html>
